let format = AVAudioFormat(standardFormatWithSampleRate: 48000, channels: 2)!
let frames = AVAudioFrameCount(48000)
let buffer = AVAudioPCMBuffer(pcmFormat: format, frameCapacity: frames)!
buffer.frameLength = frames
